import { MockProvider } from "@/lib/ai/mock";
import {
  LessonPlanSchema,
  QuizSpecSchema,
  WorksheetSpecSchema,
  RubricSpecSchema,
} from "@/lib/ai/schemas";
import type {
  CreateLessonPlanInput,
  CreateQuizInput,
  CreateWorksheetInput,
  CreateRubricInput,
  CreateExplanationInput,
} from "../types";

/**
 * Demo-mode ARTIFACT seeds (spec 20.3-20.8, fixed Jan-Sep 2026 dates).
 *
 * Lessons, quizzes, the worksheet and the rubric are generated by the MOCK
 * provider at seed time, so every seeded doc is schema-valid and honestly
 * stamped provider "mock" — the UI labels it a sample draft exactly like a
 * teacher-generated one. ONE lesson is stamped provider "gemini": it stands
 * for a page kept from the March 2026 Gemini pilot, so the UI also
 * demonstrates non-mock provenance (it is still a draft awaiting review).
 *
 * Explanations are hand-authored, realistic ICT content (provider "mock"),
 * one approved and one draft that carries an uncertaintyNote.
 *
 * MongoStore starts empty on purpose; these seeds are DemoStore-only.
 */

const TEACHER_1 = "usr-teacher-01";
const TEACHER_2 = "usr-teacher-02";

const mock = new MockProvider();

async function lessonSeed(input: {
  topic: string;
  classLevel: string;
  durationMin: number;
  objectives?: string[];
  assessmentStyle: string;
  /** Overrides the provenance stamp (used for the legacy gemini sample). */
  provenance?: { provider: "gemini" | "openai" | "mock"; model: string };
}): Promise<CreateLessonPlanInput> {
  const promptInput = {
    topic: input.topic,
    classLevel: input.classLevel,
    durationMin: input.durationMin,
    objectives: input.objectives ?? [],
    priorKnowledge: "",
    assessmentStyle: input.assessmentStyle,
  };
  const result = await mock.generate("lesson", promptInput, LessonPlanSchema);
  return {
    title: result.data.title,
    topic: input.topic,
    classLevel: input.classLevel,
    durationMin: input.durationMin,
    objectives: result.data.learningObjectives,
    content: result.data,
    promptInput,
    provider: input.provenance?.provider ?? result.provider,
    model: input.provenance?.model ?? result.model,
    createdBy: TEACHER_1,
  };
}

async function quizSeed(input: {
  topic: string;
  classLevel: string;
  questionCount: number;
  difficulty: "easy" | "medium" | "hard";
  questionTypes: string[];
  language: string;
}): Promise<CreateQuizInput> {
  const promptInput = { ...input, learningObjective: "" };
  const result = await mock.generate("quiz", promptInput, QuizSpecSchema);
  return {
    topic: input.topic,
    classLevel: input.classLevel,
    questionCount: input.questionCount,
    difficulty: input.difficulty,
    language: input.language,
    content: result.data,
    promptInput,
    provider: result.provider,
    model: result.model,
    createdBy: TEACHER_1,
  };
}

async function worksheetSeed(input: {
  topic: string;
  classLevel: string;
}): Promise<CreateWorksheetInput> {
  const promptInput = {
    topic: input.topic,
    classLevel: input.classLevel,
    sectionCount: 3,
    focus: "",
  };
  const result = await mock.generate(
    "worksheet",
    promptInput,
    WorksheetSpecSchema,
  );
  return {
    topic: input.topic,
    classLevel: input.classLevel,
    content: result.data,
    promptInput,
    provider: result.provider,
    model: result.model,
    createdBy: TEACHER_1,
  };
}

async function rubricSeed(input: {
  assignmentTitle: string;
  topic: string;
  classLevel: string;
  criteriaCount: number;
  totalPoints: number;
}): Promise<CreateRubricInput> {
  const promptInput = {
    assignmentTitle: input.assignmentTitle,
    classLevel: input.classLevel,
    criteriaCount: input.criteriaCount,
    totalPoints: input.totalPoints,
    topic: input.topic,
  };
  const result = await mock.generate("rubric", promptInput, RubricSpecSchema);
  return {
    assignmentTitle: input.assignmentTitle,
    topic: input.topic,
    classLevel: input.classLevel,
    content: result.data,
    promptInput,
    provider: result.provider,
    model: result.model,
    createdBy: TEACHER_2,
  };
}

export interface ArtifactSeeds {
  lessons: CreateLessonPlanInput[];
  quizzes: CreateQuizInput[];
  worksheets: CreateWorksheetInput[];
  rubrics: CreateRubricInput[];
  explanations: CreateExplanationInput[];
}

/** Build every artifact seed (mock-generated where content allows). */
export async function buildArtifactSeeds(): Promise<ArtifactSeeds> {
  const lessons: CreateLessonPlanInput[] = [
    await lessonSeed({
      topic: "Number Systems",
      classLevel: "HSC",
      durationMin: 40,
      objectives: [
        "Convert decimal numbers to binary using repeated division",
        "Verify a conversion by expanding binary place values",
      ],
      assessmentStyle: "exit ticket",
    }),
    await lessonSeed({
      topic: "Computer Network",
      classLevel: "SSC",
      durationMin: 35,
      assessmentStyle: "oral questioning",
    }),
    // Legacy sample kept from the March 2026 Gemini pilot (draft, unreviewed).
    await lessonSeed({
      topic: "C Programming",
      classLevel: "HSC",
      durationMin: 45,
      assessmentStyle: "written exercise",
      provenance: { provider: "gemini", model: "gemini-2.5-flash" },
    }),
  ];

  const quizzes: CreateQuizInput[] = [
    await quizSeed({
      topic: "Database",
      classLevel: "HSC",
      questionCount: 6,
      difficulty: "medium",
      questionTypes: ["mcq", "true_false", "short_answer"],
      language: "English",
    }),
    await quizSeed({
      topic: "HTML",
      classLevel: "SSC",
      questionCount: 5,
      difficulty: "easy",
      questionTypes: ["Mixed"],
      language: "Bangla",
    }),
    await quizSeed({
      topic: "Computer Security",
      classLevel: "HSC",
      questionCount: 5,
      difficulty: "medium",
      questionTypes: ["mcq", "short_answer"],
      language: "English",
    }),
  ];

  const worksheets: CreateWorksheetInput[] = [
    await worksheetSeed({ topic: "Number Systems", classLevel: "HSC" }),
  ];

  const rubrics: CreateRubricInput[] = [
    await rubricSeed({
      assignmentTitle: "Lab Report: Number Conversion Lab",
      topic: "Number Systems",
      classLevel: "HSC",
      criteriaCount: 4,
      totalPoints: 50,
    }),
  ];

  const explanations: CreateExplanationInput[] = [
    {
      question: "Why is 13 in decimal written as 1101 in binary?",
      confusion:
        "The student added the digits 1+1+0+1 and got 3, so binary made no sense to them.",
      topic: "Number Systems",
      audience: "teacher",
      content: {
        simpleExplanation:
          "Binary is not read by adding the digits — each POSITION has its own value. From the right, the positions are worth 1, 2, 4 and 8. Write 1 under the positions you use and 0 under the ones you do not: 13 = 8 + 4 + 1, so the positions 8, 4 and 1 get a 1 and the position 2 gets a 0, giving 1101.",
        analogy:
          "Think of four boxes of money: 8 taka, 4 taka, 2 taka and 1 taka. You may take each box or leave it. To collect exactly 13 taka you take the 8, the 4 and the 1 boxes and leave the 2 — the boxes you took are the 1s in 1101.",
        stepByStep: [
          "Write the place values from the right: 1, 2, 4, 8.",
          "Take the biggest value that fits into 13: that is 8. Mark 1 under it; 13 - 8 = 5 left.",
          "The next value 4 fits into 5. Mark 1; 5 - 4 = 1 left.",
          "The value 2 does not fit into 1. Mark 0 under it.",
          "The last value 1 fits exactly. Mark 1 and read the marks left to right: 1101.",
        ],
        commonMistake:
          "Students add the digits (1+1+0+1=3) instead of multiplying each digit by its place value. Always multiply first (1x8 + 1x4 + 0x2 + 1x1), then add.",
        practiceQuestion: {
          question:
            "Convert decimal 11 to binary using the place-value method.",
          answer: "1011 (8 + 2 + 1; the 4 position gets 0).",
        },
      },
      promptInput: {
        question: "Why is 13 in decimal written as 1101 in binary?",
        topic: "Number Systems",
        audience: "teacher",
      },
      provider: "mock",
      model: "mock-template-v1",
      createdBy: TEACHER_1,
    },
    {
      question: "When does an XOR gate output 1?",
      confusion:
        "The student thought XOR outputs 1 whenever any input is 1, like OR.",
      topic: "Logic Gates",
      audience: "teacher",
      content: {
        simpleExplanation:
          "XOR (exclusive OR) outputs 1 only when the two inputs are DIFFERENT — one is 1 and the other is 0. If both inputs are the same (both 0 or both 1) the output is 0. That is the 'exclusive' part: it excludes the case where both are on.",
        analogy:
          "A two-way light switch in a staircase: the light is on only when the two switches are in different positions. Flip either one and they match or mismatch again.",
        stepByStep: [
          "Write the two inputs, e.g. A = 1, B = 0.",
          "Ask one question: are A and B different?",
          "If they are different, the output is 1.",
          "If they are the same, the output is 0.",
          "Check the full truth table: 0-0 gives 0, 0-1 gives 1, 1-0 gives 1, 1-1 gives 0.",
        ],
        commonMistake:
          "Treating XOR like OR and answering 1 for the 1-1 case. OR answers 1 there; XOR answers 0.",
        practiceQuestion: {
          question:
            "An XOR gate has inputs A = 1 and B = 1. What is the output, and why?",
          answer:
            "0, because the inputs are the same — XOR outputs 1 only when they differ.",
        },
        uncertaintyNote:
          "The staircase-switch analogy assumes a standard two-way switching circuit; verify the wiring example against your textbook's figure before using it in class.",
      },
      promptInput: {
        question: "When does an XOR gate output 1?",
        topic: "Logic Gates",
        audience: "teacher",
      },
      provider: "mock",
      model: "mock-template-v1",
      createdBy: TEACHER_2,
    },
  ];

  return { lessons, quizzes, worksheets, rubrics, explanations };
}

